import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
if (!process.env.VOLTER_WORLD) throw new Error('Run this app through its World.');
const username = process.env.HN_USERNAME;
assert.ok(username && process.env.HN_PASSWORD);
async function json(url) {
  const response = await fetch(url);
  assert.equal(response.status, 200);
  return response.json();
}
const userUrl = `https://hacker-news.firebaseio.com/v0/user/${encodeURIComponent(username)}.json`;
const title = 'Show HN: a small public dataset explorer';
let saved;
if (process.argv[2] === 'readback') {
  saved = JSON.parse(readFileSync('story.json', 'utf8'));
} else {
  const login = await fetch('https://news.ycombinator.com/login', { method: 'POST', redirect: 'manual', body: new URLSearchParams({ acct: username, pw: process.env.HN_PASSWORD, goto: 'submit' }) });
  assert.equal(login.status, 302);
  const cookie = login.headers.get('set-cookie')?.split(';')[0];
  assert.ok(cookie);
  const form = await fetch('https://news.ycombinator.com/submit', { headers: { cookie } });
  assert.equal(form.status, 200);
  const html = await form.text();
  const fnid = /name="fnid" value="([^"]+)"/.exec(html)?.[1];
  assert.ok(fnid);
  const submitted = await fetch('https://news.ycombinator.com/r', { method: 'POST', redirect: 'manual', headers: { cookie }, body: new URLSearchParams({ fnid, fnop: 'submit-page', title, url: 'https://example.com/dataset-explorer', text: '' }) });
  assert.equal(submitted.status, 302);
  const user = await json(userUrl);
  assert.equal(user.id, username);
  assert.ok(user.submitted.length > 0);
  saved = { id: user.submitted[0] };
  writeFileSync('story.json', JSON.stringify(saved), { mode: 0o600 });
}
const story = await json(`https://hacker-news.firebaseio.com/v0/item/${saved.id}.json`);
assert.equal(story.by, username);
assert.equal(story.title, title);
assert.equal(story.url, 'https://example.com/dataset-explorer');
const user = await json(userUrl);
assert.ok(user.submitted.includes(saved.id));
console.log(JSON.stringify({ story: saved.id, author: user.id, retained: process.argv[2] === 'readback' }));
